insert into public.passages (source_id, ordinal, content, language)
values (
  '5eed0000-0000-4000-8000-000000000005'::uuid,
  2,
  $passage$The House of Wisdom existed as a part of the major Translation Movement taking place during the Abbasid Era, translating works from Greek and Syriac to Arabic, but it is unlikely that the House of Wisdom existed as the sole center of such work, as major translation efforts arose in Cairo and Damascus even earlier than the proposed establishment of the House of Wisdom. This translation movement lent momentum to a great deal of original research occurring in the Muslim world, which had access to texts from Greek, Persian, and Indian sources. The rise of advanced research into mathematics, astronomy, philosophy, and medicine was the beginning of Arabic science, and drove demand for more and updated translations.$passage$,
  'en'
) on conflict (source_id, ordinal) do nothing;

